// Generated by AI QA Agent from .qa/scenarios/login.json — regenerated when scenarios change.
import { test, expect, type Page, type Locator } from '@company/ai-qa-agent/playwright';

const VALID_EMAIL = 'demo@shop.test';
const VALID_PASSWORD = 'password123';
const EMAIL_ERROR = 'Enter a valid email address';
const PASSWORD_ERROR = 'Password must be at least 8 characters';
const FORM_ERROR = 'Invalid email or password';
const WELCOME = 'Welcome back, Demo User';

// Local page helpers -------------------------------------------------------

function form(page: Page): Locator {
  return page.getByRole('form', { name: 'Sign in' });
}

function emailInput(page: Page): Locator {
  return page.getByLabel('Email');
}

function passwordInput(page: Page): Locator {
  return page.getByLabel('Password');
}

// The form contains a single button; its name toggles between 'Sign in' and 'Signing in…'.
function submitButton(page: Page): Locator {
  return form(page).getByRole('button');
}

function heading(page: Page, name: string): Locator {
  return page.getByRole('heading', { level: 1, name, exact: true });
}

function formAlert(page: Page): Locator {
  return page.getByRole('alert').filter({ hasText: FORM_ERROR });
}

async function fillCredentials(page: Page, email: string, password: string) {
  await emailInput(page).fill(email);
  await passwordInput(page).fill(password);
}

async function submit(page: Page) {
  await submitButton(page).click();
}

async function expectNoFieldErrors(page: Page) {
  await expect(page.getByText(EMAIL_ERROR, { exact: true })).toHaveCount(0);
  await expect(page.getByText(PASSWORD_ERROR, { exact: true })).toHaveCount(0);
}

async function box(locator: Locator) {
  const b = await locator.boundingBox();
  expect(b, 'element should have a bounding box').not.toBeNull();
  return b!;
}

// Tests --------------------------------------------------------------------

test.describe('/login', () => {
  test(
    'LOGIN-001: Valid credentials sign the user in and show the welcome heading',
    { tag: ['@functional', '@auth', '@desktop', '@high'] },
    async ({ page }) => {
      await test.step('Open /login', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      await test.step("Type 'demo@shop.test' into 'Email' and 'password123' into 'Password'", async () => {
        await emailInput(page).fill(VALID_EMAIL);
        await passwordInput(page).fill(VALID_PASSWORD);
      });

      await test.step("Click the 'Sign in' button", async () => {
        await submit(page);
      });

      await test.step('Wait for the h1 to change and verify the success state', async () => {
        await expect(heading(page, WELCOME)).toBeVisible();
        await expect(form(page)).toHaveCount(0);
        await expect(emailInput(page)).toHaveCount(0);
        await expect(passwordInput(page)).toHaveCount(0);
        await expect(page.getByRole('button', { name: 'Sign in', exact: true })).toHaveCount(0);
        await expect(page.getByRole('alert').filter({ hasText: FORM_ERROR })).toHaveCount(0);
        await expectNoFieldErrors(page);
        await expect(page).toHaveURL(/\/login$/);
        await expect(page.getByRole('link', { name: 'Sign in to your account' })).toBeVisible();
        await expect(page.getByRole('link', { name: 'Home', exact: true })).toBeVisible();
      });
    },
  );

  test(
    'LOGIN-002: Submitting the empty form shows both field errors at once',
    { tag: ['@functional', '@auth', '@desktop', '@high'] },
    async ({ page }) => {
      await test.step('Open /login', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      await test.step("Click the 'Sign in' button without typing anything", async () => {
        await submit(page);
      });

      await test.step('Both field errors are shown at the same time', async () => {
        await expect(page.getByText(EMAIL_ERROR, { exact: true })).toBeVisible();
        await expect(page.getByText(PASSWORD_ERROR, { exact: true })).toBeVisible();
      });

      await test.step('Inputs are marked invalid and described by their errors', async () => {
        await expect(emailInput(page)).toHaveAttribute('aria-invalid', 'true');
        await expect(passwordInput(page)).toHaveAttribute('aria-invalid', 'true');
        const emailDescribedBy = await emailInput(page).getAttribute('aria-describedby');
        const passwordDescribedBy = await passwordInput(page).getAttribute('aria-describedby');
        expect(emailDescribedBy).toBeTruthy();
        expect(passwordDescribedBy).toBeTruthy();
        await expect(page.locator(`[id="${emailDescribedBy}"]`)).toHaveText(EMAIL_ERROR);
        await expect(page.locator(`[id="${passwordDescribedBy}"]`)).toHaveText(PASSWORD_ERROR);
        await expect(emailInput(page)).toHaveAccessibleDescription(EMAIL_ERROR);
        await expect(passwordInput(page)).toHaveAccessibleDescription(PASSWORD_ERROR);
      });

      await test.step('No form-level alert, button unchanged, h1 unchanged', async () => {
        await expect(formAlert(page)).toHaveCount(0);
        await expect(submitButton(page)).toHaveText('Sign in');
        await expect(submitButton(page)).toBeEnabled();
        await expect(heading(page, 'Sign in')).toBeVisible();
      });
    },
  );

  test(
    'LOGIN-003: Wrong credentials show a form-level alert, keep the form usable, and replace field errors',
    { tag: ['@functional', '@auth', '@desktop', '@high'] },
    async ({ page }) => {
      await test.step('Open /login', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      await test.step("Click 'Sign in' with empty fields so both field errors appear", async () => {
        await submit(page);
        await expect(page.getByText(EMAIL_ERROR, { exact: true })).toBeVisible();
        await expect(page.getByText(PASSWORD_ERROR, { exact: true })).toBeVisible();
      });

      await test.step("Type wrong credentials and click 'Sign in'", async () => {
        await fillCredentials(page, 'wrong@shop.test', 'wrongpass1');
        await submit(page);
      });

      await test.step("Wait for the button to return to 'Sign in'", async () => {
        await expect(formAlert(page)).toBeVisible();
        await expect(submitButton(page)).toHaveText('Sign in');
        await expect(submitButton(page)).toBeEnabled();
      });

      await test.step('Verify the failed-attempt state', async () => {
        await expect(page.getByRole('alert')).toHaveText(FORM_ERROR);
        await expectNoFieldErrors(page);
        await expect(emailInput(page)).toHaveValue('wrong@shop.test');
        await expect(passwordInput(page)).toHaveValue('wrongpass1');
        await expect(heading(page, 'Sign in')).toBeVisible();
        await expect(page.getByRole('heading', { level: 1, name: WELCOME })).toHaveCount(0);
      });

      await test.step('Correct the credentials and sign in', async () => {
        await passwordInput(page).fill(VALID_PASSWORD);
        await emailInput(page).fill(VALID_EMAIL);
        await submit(page);
        await expect(heading(page, WELCOME)).toBeVisible();
      });
    },
  );

  test(
    'LOGIN-004: Malformed email addresses are rejected with the email error only',
    { tag: ['@functional', '@auth', '@desktop', '@medium'] },
    async ({ page }) => {
      await test.step('Open /login', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      const malformed = [
        { email: 'demo@shop', note: 'no domain suffix' },
        { email: 'demoshop.test', note: 'no @' },
        { email: 'demo @shop.test', note: 'contains a space' },
      ];

      for (const { email, note } of malformed) {
        await test.step(`Submit '${email}' (${note}) with a valid password`, async () => {
          await fillCredentials(page, email, VALID_PASSWORD);
          await submit(page);

          await expect(page.getByText(EMAIL_ERROR, { exact: true })).toBeVisible();
          await expect(emailInput(page)).toHaveAttribute('aria-invalid', 'true');
          await expect(page.getByText(PASSWORD_ERROR, { exact: true })).toHaveCount(0);
          await expect(passwordInput(page)).toHaveAttribute('aria-invalid', 'false');

          // No login request: no loading label, no form-level alert, still on the sign-in form
          await expect(submitButton(page)).toHaveText('Sign in');
          await expect(submitButton(page)).toBeEnabled();
          await expect(formAlert(page)).toHaveCount(0);
          await expect(heading(page, 'Sign in')).toBeVisible();
        });
      }
    },
  );

  test(
    'LOGIN-005: Password shorter than 8 characters is rejected; exactly 8 characters is accepted for validation',
    { tag: ['@functional', '@auth', '@desktop', '@medium'] },
    async ({ page }) => {
      await test.step('Open /login', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      await test.step("Submit 'demo@shop.test' with a 7-character password", async () => {
        await fillCredentials(page, VALID_EMAIL, 'pass123');
        await submit(page);

        await expect(page.getByText(PASSWORD_ERROR, { exact: true })).toBeVisible();
        await expect(page.getByText(EMAIL_ERROR, { exact: true })).toHaveCount(0);
        await expect(passwordInput(page)).toHaveAttribute('aria-invalid', 'true');
        await expect(submitButton(page)).toHaveText('Sign in');
        await expect(submitButton(page)).toBeEnabled();
        await expect(formAlert(page)).toHaveCount(0);
      });

      await test.step('Submit an 8-character password: login is attempted and fails', async () => {
        await passwordInput(page).fill('wrongpas');
        await submit(page);

        await expect(submitButton(page)).toHaveText('Signing in…');
        await expect(page.getByText(PASSWORD_ERROR, { exact: true })).toHaveCount(0);

        await expect(formAlert(page)).toBeVisible();
        await expect(page.getByRole('alert')).toHaveText(FORM_ERROR);
        await expect(submitButton(page)).toHaveText('Sign in');
      });
    },
  );

  test(
    'LOGIN-006: Submit button shows loading state while signing in',
    { tag: ['@functional', '@auth', '@desktop', '@medium'] },
    async ({ page }) => {
      await test.step('Open /login', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      await test.step("Fill 'Email' and 'Password'", async () => {
        await fillCredentials(page, VALID_EMAIL, VALID_PASSWORD);
      });

      await test.step("Click 'Sign in' and immediately inspect the button", async () => {
        await submit(page);
        const button = submitButton(page);
        await expect(button).toHaveText('Signing in…');
        await expect(button).toBeDisabled();
        await expect(button).toHaveCSS('cursor', 'not-allowed');
        await expect(button).not.toHaveCSS('opacity', '1');
      });

      await test.step('Clicking the disabled button again does nothing', async () => {
        // A native click on a disabled button dispatches no click event; no second submission occurs.
        await submitButton(page)
          .evaluate((el) => (el as HTMLButtonElement).click())
          .catch(() => {
            // The form may already have been replaced by the welcome section; that is fine.
          });
      });

      await test.step('After the delay the welcome heading is shown', async () => {
        await expect(heading(page, WELCOME)).toBeVisible();
        await expect(form(page)).toHaveCount(0);
        await expect(page.getByRole('alert').filter({ hasText: FORM_ERROR })).toHaveCount(0);
      });
    },
  );

  test(
    'LOGIN-007: Email is case-insensitive but password is case-sensitive',
    { tag: ['@functional', '@auth', '@desktop', '@medium'] },
    async ({ page }) => {
      await test.step('Open /login', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      await test.step("Sign in with 'DEMO@SHOP.TEST' / 'password123'", async () => {
        await fillCredentials(page, 'DEMO@SHOP.TEST', VALID_PASSWORD);
        await submit(page);
        await expect(heading(page, WELCOME)).toBeVisible();
      });

      await test.step('Reload /login: the sign-in form is shown again', async () => {
        await page.reload();
        await expect(heading(page, 'Sign in')).toBeVisible();
        await expect(form(page)).toBeVisible();
        await expect(page.getByRole('heading', { level: 1, name: WELCOME })).toHaveCount(0);
      });

      await test.step("Sign in with 'demo@shop.test' / 'Password123'", async () => {
        await fillCredentials(page, VALID_EMAIL, 'Password123');
        await submit(page);
        await expect(formAlert(page)).toBeVisible();
        await expect(page.getByRole('alert')).toHaveText(FORM_ERROR);
        await expect(page.getByRole('heading', { level: 1, name: WELCOME })).toHaveCount(0);
        await expect(heading(page, 'Sign in')).toBeVisible();
      });
    },
  );

  test(
    'LOGIN-008: Header link opens the sign-in page and the form resets after navigating away',
    { tag: ['@functional', '@navigation', '@desktop', '@medium'] },
    async ({ page }) => {
      const signInLink = page.getByRole('link', { name: 'Sign in to your account' });

      await test.step('Open /', async () => {
        await page.goto('/');
        await expect(signInLink).toBeVisible();
      });

      await test.step("Click the header link 'Sign in to your account'", async () => {
        await signInLink.click();
        await expect(page).toHaveURL(/\/login$/);
        await expect(heading(page, 'Sign in')).toBeVisible();
        await expect(emailInput(page)).toBeVisible();
        await expect(passwordInput(page)).toBeVisible();
        await expect(submitButton(page)).toHaveText('Sign in');
      });

      await test.step("Sign in with 'demo@shop.test' / 'password123'", async () => {
        await fillCredentials(page, VALID_EMAIL, VALID_PASSWORD);
        await submit(page);
        await expect(heading(page, WELCOME)).toBeVisible();
      });

      await test.step("Click 'Home', then 'Sign in to your account' again", async () => {
        await page.getByRole('link', { name: 'Home', exact: true }).click();
        await expect(page).toHaveURL(/\/$/);
        await signInLink.click();
        await expect(page).toHaveURL(/\/login$/);
      });

      await test.step('The sign-in form is shown again with empty fields', async () => {
        await expect(heading(page, 'Sign in')).toBeVisible();
        await expect(page.getByRole('heading', { level: 1, name: WELCOME })).toHaveCount(0);
        await expect(emailInput(page)).toHaveValue('');
        await expect(passwordInput(page)).toHaveValue('');
      });
    },
  );

  test(
    'LOGIN-009: Login form matches the Figma design tokens on desktop',
    { tag: ['@visual', '@auth', '@desktop', '@medium'] },
    async ({ page, qa }) => {
      await test.step('Open /login at desktop viewport', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      await test.step("Inspect the h1 'Sign in'", async () => {
        await qa.expectDesignTokens(
          heading(page, 'Sign in'),
          { fontFamily: 'Inter', fontWeight: '700', fontSize: '40px', lineHeight: '48px' },
          "h1 'Sign in'",
        );
      });

      await test.step("Inspect the 'Email' and 'Password' inputs", async () => {
        await qa.expectDesignTokens(emailInput(page), { height: '44px' }, "'Email' input");
        await qa.expectDesignTokens(passwordInput(page), { height: '44px' }, "'Password' input");
      });

      await test.step("Inspect the 'Sign in' submit button", async () => {
        await qa.expectDesignTokens(
          submitButton(page),
          {
            backgroundColor: '#2563EB',
            color: '#FFFFFF',
            borderRadius: '8px',
            height: '44px',
            width: '400px',
            fontFamily: 'Inter',
            fontSize: '16px',
            fontWeight: '600',
            lineHeight: '24px',
          },
          "'Sign in' submit button",
        );
        await expect(submitButton(page)).toHaveCSS('border-top-width', '0px');
        await expect(submitButton(page)).toHaveCSS('border-right-width', '0px');
        await expect(submitButton(page)).toHaveCSS('border-bottom-width', '0px');
        await expect(submitButton(page)).toHaveCSS('border-left-width', '0px');
      });

      await test.step('Inspect the form width and position', async () => {
        await qa.expectDesignTokens(form(page), { width: '400px' }, "'Sign in' form");

        const header = await box(page.getByRole('banner'));
        expect(header.height).toBe(64);

        // The auth section (h1 + form) starts 32px below the header and is left-aligned in the container.
        const section = await box(heading(page, 'Sign in').locator('..'));
        expect(section.y - (header.y + header.height)).toBe(32);

        const main = page.getByRole('main');
        const mainBox = await box(main);
        const paddingLeft = parseFloat(
          await main.evaluate((el) => getComputedStyle(el).paddingLeft),
        );
        expect(section.x).toBeCloseTo(mainBox.x + paddingLeft, 0);
        expect((await box(form(page))).x).toBeCloseTo(mainBox.x + paddingLeft, 0);
      });
    },
  );

  test(
    'LOGIN-010: Login page fits a 390px mobile viewport and header nav collapses',
    { tag: ['@responsive', '@auth', '@mobile', '@medium'] },
    async ({ page, qa }) => {
      const VIEWPORT_WIDTH = 390;
      const GUTTER = 24;

      await test.step('Open /login at mobile viewport', async () => {
        await page.goto('/login');
        await expect(heading(page, 'Sign in')).toBeVisible();
      });

      await test.step('Header shows a menu toggle and the nav links are collapsed', async () => {
        await expect(page.getByRole('button', { name: 'Open menu' })).toBeVisible();
        await expect(page.getByRole('navigation', { name: 'Main' })).toBeHidden();
        await expect(page.getByRole('link', { name: 'Sign in to your account' })).toBeHidden();

        const toggle = await box(page.getByRole('button', { name: 'Open menu' }));
        expect(toggle.x + toggle.width, 'menu toggle sits on the right').toBeGreaterThan(
          VIEWPORT_WIDTH / 2,
        );
      });

      await test.step('No horizontal scrolling', async () => {
        await qa.expectNoHorizontalOverflow();
        const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
        expect(scrollWidth).toBe(VIEWPORT_WIDTH);
      });

      await test.step('Fields and button fit within the viewport gutters, stacked, 44px tall', async () => {
        const email = await box(emailInput(page));
        const password = await box(passwordInput(page));
        const button = await box(submitButton(page));

        for (const control of [email, password, button]) {
          expect(control.x).toBeGreaterThanOrEqual(GUTTER);
          expect(control.x + control.width).toBeLessThanOrEqual(VIEWPORT_WIDTH - GUTTER);
          expect(control.height).toBe(44);
        }

        expect(email.y + email.height).toBeLessThanOrEqual(password.y);
        expect(password.y + password.height).toBeLessThanOrEqual(button.y);
      });

      await test.step('Submit the empty form: both validation messages are fully visible', async () => {
        await submit(page);
        for (const message of [EMAIL_ERROR, PASSWORD_ERROR]) {
          const error = page.getByText(message, { exact: true });
          await expect(error).toBeVisible();
          await expect(error).toBeInViewport({ ratio: 1 });
          const b = await box(error);
          expect(b.x).toBeGreaterThanOrEqual(0);
          expect(b.x + b.width).toBeLessThanOrEqual(VIEWPORT_WIDTH);
          const clipped = await error.evaluate((el) => el.scrollWidth > el.clientWidth);
          expect(clipped, `'${message}' should not be clipped`).toBe(false);
        }
        await qa.expectNoHorizontalOverflow();
      });

      await test.step("Sign in with 'demo@shop.test' / 'password123'", async () => {
        await fillCredentials(page, VALID_EMAIL, VALID_PASSWORD);
        await submit(page);

        const welcome = heading(page, WELCOME);
        await expect(welcome).toBeVisible();
        const b = await box(welcome);
        expect(b.x).toBeGreaterThanOrEqual(0);
        expect(b.x + b.width).toBeLessThanOrEqual(VIEWPORT_WIDTH);
        const overflows = await welcome.evaluate((el) => el.scrollWidth > el.clientWidth);
        expect(overflows, 'welcome heading should not overflow').toBe(false);
        await qa.expectNoHorizontalOverflow();
      });
    },
  );
});
